// Bitmemiş etkinlikler, başlangıç zamanına göre; (starts_at, id) ile
// sayfalanır.
func (q *Queries) ListUpcomingEvents(ctx context.Context, arg ListUpcomingEventsParams) ([]ListUpcomingEventsRow, error) {
	rows, err := q.db.Query(ctx, listUpcomingEvents,
		arg.TayfaID,
		arg.Now,
		arg.AfterStartsAt,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUpcomingEventsRow{}
	for rows.Next() {
		var i ListUpcomingEventsRow
		if err := rows.Scan(
			&i.ID,
			&i.TayfaID,
			&i.Type,
			&i.Mode,
			&i.Title,
			&i.Description,
			&i.StartsAt,
			&i.EndsAt,
			&i.MeetingPointName,
			&i.MeetingLat,
			&i.MeetingLng,
			&i.City,
			&i.District,
			&i.OnlineUrl,
			&i.Capacity,
			&i.Status,
			&i.CancelledAt,
			&i.CancelReason,
			&i.SeriesID,
			&i.SeriesOverride,
			&i.Discoverable,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CoverUploadID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

