const nextWaitlisted = `-- name: NextWaitlisted :many
SELECT user_id FROM event_rsvps
WHERE event_id = $1 AND status = 'waitlist'
ORDER BY updated_at, user_id
LIMIT $2
FOR UPDATE
`

type NextWaitlistedParams struct {
	EventID pgtype.UUID
	N       int32
}

// Bekleme listesinin başı: en eski kayıt önce. Çağıran etkinlik satırını
// zaten kilitlemiştir; satır kilidi aynı kaydın iki kez terfisini de önler.
func (q *Queries) NextWaitlisted(ctx context.Context, arg NextWaitlistedParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, nextWaitlisted, arg.EventID, arg.N)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var user_id pgtype.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

