const updateEvent = `-- name: UpdateEvent :execrows
UPDATE events
SET title = $1, description = $2, starts_at = $3, ends_at = $4,
    mode = $5, meeting_point_name = $6, meeting_lat = $7,
    meeting_lng = $8, city = $9, district = $10, online_url = $11,
    capacity = $12, discoverable = $13,
    series_override = (series_id IS NOT NULL)
WHERE tayfa_id = $14 AND id = $15 AND deleted_at IS NULL AND status = 'scheduled'
`

type UpdateEventParams struct {
	Title            string
	Description      pgtype.Text
	StartsAt         pgtype.Timestamptz
	EndsAt           pgtype.Timestamptz
	Mode             string
	MeetingPointName pgtype.Text
	MeetingLat       pgtype.Float8
	MeetingLng       pgtype.Float8
	City             pgtype.Text
	District         pgtype.Text
	OnlineUrl        pgtype.Text
	Capacity         pgtype.Int4
	Discoverable     bool
	TayfaID          pgtype.UUID
	ID               pgtype.UUID
}

// Seri örneği elle düzenlenince seri güncellemeleri ona dokunmaz.
func (q *Queries) UpdateEvent(ctx context.Context, arg UpdateEventParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateEvent,
		arg.Title,
		arg.Description,
		arg.StartsAt,
		arg.EndsAt,
		arg.Mode,
		arg.MeetingPointName,
		arg.MeetingLat,
		arg.MeetingLng,
		arg.City,
		arg.District,
		arg.OnlineUrl,
		arg.Capacity,
		arg.Discoverable,
		arg.TayfaID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
